func (o RequestUsageSlice) pkIN() dialect.Expression {
	if len(o) == 0 {
		return sqlite.Raw("NULL")
	}

	return sqlite.Quote("request_usage", "request_id").In(bob.ExpressionFunc(func(ctx context.Context, w io.StringWriter, d bob.Dialect, start int) ([]any, error) {
		pkPairs := make([]bob.Expression, len(o))
		for i, row := range o {
			pkPairs[i] = row.primaryKeyVals()
		}
		return bob.ExpressSlice(ctx, w, d, start, pkPairs, "", ", ", "")
	}))
}

// copyMatchingRows finds models in the given slice that have the same primary key
// then it first copies the existing relationships from the old model to the new model
// and then replaces the old model in the slice with the new model
func (o RequestUsageSlice) copyMatchingRows(from ...*RequestUsage) {
	fromByPK := make(map[string]*RequestUsage, len(from))
	for _, new := range from {
		// keep the first row for each key, like the nested loop did
		if _, ok := fromByPK[new.RequestID]; !ok {
			fromByPK[new.RequestID] = new
		}
	}

	for i, old := range o {
		new, ok := fromByPK[old.RequestID]
		if !ok {
			continue
		}
		new.R = old.R
		o[i] = new
	}
}

// UpdateMod modifies an update query with "WHERE primary_key IN (o...)"
func (o RequestUsageSlice) UpdateMod() bob.Mod[*dialect.UpdateQuery] {
	return bob.ModFunc[*dialect.UpdateQuery](func(q *dialect.UpdateQuery) {
		q.AppendHooks(func(ctx context.Context, exec bob.Executor) (context.Context, error) {
			return RequestUsages.BeforeUpdateHooks.RunHooks(ctx, exec, o)
		})

		q.AppendLoader(bob.LoaderFunc(func(ctx context.Context, exec bob.Executor, retrieved any) error {
			var err error
			switch retrieved := retrieved.(type) {
			case *RequestUsage:
				o.copyMatchingRows(retrieved)
			case []*RequestUsage:
				o.copyMatchingRows(retrieved...)
			case RequestUsageSlice:
				o.copyMatchingRows(retrieved...)
			default:
				// If the retrieved value is not a RequestUsage or a slice of RequestUsage
				// then run the AfterUpdateHooks on the slice
				_, err = RequestUsages.AfterUpdateHooks.RunHooks(ctx, exec, o)
			}

			return err
		}))

		q.AppendWhere(o.pkIN())
	})
}

// DeleteMod modifies an delete query with "WHERE primary_key IN (o...)"
func (o RequestUsageSlice) DeleteMod() bob.Mod[*dialect.DeleteQuery] {
	return bob.ModFunc[*dialect.DeleteQuery](func(q *dialect.DeleteQuery) {
		q.AppendHooks(func(ctx context.Context, exec bob.Executor) (context.Context, error) {
			return RequestUsages.BeforeDeleteHooks.RunHooks(ctx, exec, o)
		})

		q.AppendLoader(bob.LoaderFunc(func(ctx context.Context, exec bob.Executor, retrieved any) error {
			var err error
			switch retrieved := retrieved.(type) {
			case *RequestUsage:
				o.copyMatchingRows(retrieved)
			case []*RequestUsage:
				o.copyMatchingRows(retrieved...)
			case RequestUsageSlice:
				o.copyMatchingRows(retrieved...)
			default:
				// If the retrieved value is not a RequestUsage or a slice of RequestUsage
				// then run the AfterDeleteHooks on the slice
				_, err = RequestUsages.AfterDeleteHooks.RunHooks(ctx, exec, o)
			}

			return err
		}))

		q.AppendWhere(o.pkIN())
	})
}

