// RequestProxyRequest starts a query for related objects on proxy_requests
func (o *RequestUsage) RequestProxyRequest(mods ...bob.Mod[*dialect.SelectQuery]) ProxyRequestsQuery {
	return ProxyRequests.Query(append(mods,
		sm.Where(ProxyRequests.Columns.ID.EQ(sqlite.Arg(o.RequestID))),
	)...)
}

func (os RequestUsageSlice) RequestProxyRequest(mods ...bob.Mod[*dialect.SelectQuery]) ProxyRequestsQuery {
	PKArgSlice := make([]bob.Expression, len(os))
	for i, o := range os {
		PKArgSlice[i] = sqlite.ArgGroup(o.RequestID)
	}
	PKArgExpr := sqlite.Group(PKArgSlice...)

	return ProxyRequests.Query(append(mods,
		sm.Where(sqlite.Group(ProxyRequests.Columns.ID).OP("IN", PKArgExpr)),
	)...)
}

func attachRequestUsageRequestProxyRequest0(ctx context.Context, exec bob.Executor, count int, requestUsage0 *RequestUsage, proxyRequest1 *ProxyRequest) (*RequestUsage, error) {
	setter := &RequestUsageSetter{
		RequestID: func() *string { return &proxyRequest1.ID }(),
	}

	err := requestUsage0.Update(ctx, exec, setter)
	if err != nil {
		return nil, fmt.Errorf("attachRequestUsageRequestProxyRequest0: %w", err)
	}

	return requestUsage0, nil
}

func (requestUsage0 *RequestUsage) InsertRequestProxyRequest(ctx context.Context, exec bob.Executor, related *ProxyRequestSetter) error {
	var err error

	proxyRequest1, err := ProxyRequests.Insert(related).One(ctx, exec)
	if err != nil {
		return fmt.Errorf("inserting related objects: %w", err)
	}

	_, err = attachRequestUsageRequestProxyRequest0(ctx, exec, 1, requestUsage0, proxyRequest1)
	if err != nil {
		return err
	}

	requestUsage0.R.RequestProxyRequest = proxyRequest1
	requestUsage0.R.Loaded.RequestProxyRequest = true

	return nil
}

func (requestUsage0 *RequestUsage) AttachRequestProxyRequest(ctx context.Context, exec bob.Executor, proxyRequest1 *ProxyRequest) error {
	var err error

	_, err = attachRequestUsageRequestProxyRequest0(ctx, exec, 1, requestUsage0, proxyRequest1)
	if err != nil {
		return err
	}

	requestUsage0.R.RequestProxyRequest = proxyRequest1
	requestUsage0.R.Loaded.RequestProxyRequest = true

	return nil
}
